-- =====================================================================
-- oracle_plsql/01_schema.sql   (Oracle Database 19c / 23ai, SQL*Plus or SQLcl)
-- Purpose : The tables the PL/SQL programs in 02_programs.sql touch, translated
--           from sql/01_schema.sql. Additional Experiment 2 (comparison only:
--           the project itself runs on MySQL 8.0).
-- Translation notes
--   * INT/DECIMAL -> NUMBER(p[,s]); VARCHAR -> VARCHAR2; DATETIME -> DATE
--     (an Oracle DATE always carries a time of day).
--   * AUTO_INCREMENT -> GENERATED BY DEFAULT AS IDENTITY (12c+).
--   * ENUM -> VARCHAR2 + CHECK (... IN (...)); BOOLEAN -> NUMBER(1) CHECK IN (0,1)
--     (SQL BOOLEAN columns exist only from 23ai; NUMBER(1) works on 19c too).
--   * Generated STORED column -> virtual column (computed when read).
--   * No IF EXISTS on DROP TABLE before 23ai, so a PL/SQL block drops old copies.
-- Run as an ordinary schema user, e.g. sqlplus cafe/cafe@//localhost:1521/FREEPDB1 @01_schema.sql
-- =====================================================================
BEGIN
  FOR t IN (SELECT table_name FROM user_tables
             WHERE table_name IN ('PAYMENTS', 'RENTALS_RESERVATIONS', 'CAFE_TABLES',
                                  'CUSTOMERS', 'MEMBERSHIP_TIERS')) LOOP
    EXECUTE IMMEDIATE 'DROP TABLE ' || t.table_name || ' CASCADE CONSTRAINTS PURGE';
  END LOOP;
END;
/

CREATE TABLE Membership_Tiers (
  tier_id                NUMBER(3) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tier_name              VARCHAR2(20) NOT NULL UNIQUE,
  annual_fee             NUMBER(8,2) DEFAULT 0 NOT NULL,
  max_concurrent_rentals NUMBER(3) NOT NULL,
  max_session_hours      NUMBER(3) NOT NULL,
  max_takehome_days      NUMBER(3) NOT NULL,
  discount_pct           NUMBER(5,2) DEFAULT 0 NOT NULL,
  CONSTRAINT chk_tier_discount CHECK (discount_pct BETWEEN 0 AND 50),
  CONSTRAINT chk_tier_limits   CHECK (max_concurrent_rentals >= 1
                                      AND max_session_hours BETWEEN 1 AND 13
                                      AND max_takehome_days >= 1)
);

CREATE TABLE Customers (
  customer_id       NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  first_name        VARCHAR2(50)  NOT NULL,
  last_name         VARCHAR2(50)  NOT NULL,
  email             VARCHAR2(120) NOT NULL UNIQUE,
  phone             VARCHAR2(15)  NOT NULL UNIQUE,
  date_of_birth     DATE NOT NULL,
  tier_id           NUMBER(3) NOT NULL,
  join_date         DATE DEFAULT TRUNC(SYSDATE) NOT NULL,
  membership_expiry DATE NOT NULL,
  status            VARCHAR2(10) DEFAULT 'Active' NOT NULL,
  CONSTRAINT fk_customer_tier FOREIGN KEY (tier_id) REFERENCES Membership_Tiers(tier_id),
  CONSTRAINT chk_customer_status CHECK (status IN ('Active', 'Suspended', 'Inactive')),
  CONSTRAINT chk_customer_email  CHECK (email LIKE '%_@_%._%'),
  CONSTRAINT chk_customer_phone  CHECK (REGEXP_LIKE(phone, '^[+]?[0-9]{10,14}$')),
  CONSTRAINT chk_customer_dob    CHECK (date_of_birth < join_date),
  CONSTRAINT chk_customer_expiry CHECK (membership_expiry >= join_date)
);
CREATE INDEX idx_customer_name ON Customers (last_name, first_name);

CREATE TABLE Cafe_Tables (
  table_id         NUMBER(5) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  table_code       VARCHAR2(8) NOT NULL UNIQUE,
  zone             VARCHAR2(12) NOT NULL,
  seating_capacity NUMBER(2) NOT NULL,
  hourly_rate      NUMBER(8,2) NOT NULL,
  is_accessible    NUMBER(1) DEFAULT 0 NOT NULL,
  is_active        NUMBER(1) DEFAULT 1 NOT NULL,
  CONSTRAINT chk_table_zone     CHECK (zone IN ('Main_Hall', 'Quiet_Corner', 'Party_Room', 'Patio')),
  CONSTRAINT chk_table_capacity CHECK (seating_capacity BETWEEN 2 AND 12),
  CONSTRAINT chk_table_rate     CHECK (hourly_rate >= 0),
  CONSTRAINT chk_table_flags    CHECK (is_accessible IN (0, 1) AND is_active IN (0, 1))
);

-- copy_id is kept as a plain column: Game_Copies is not part of this comparison.
CREATE TABLE Rentals_Reservations (
  booking_id       NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  customer_id      NUMBER(10) NOT NULL,
  table_id         NUMBER(5) NULL,
  copy_id          NUMBER(10) NULL,
  booking_type     VARCHAR2(10) NOT NULL,
  party_size       NUMBER(3) NULL,
  reserved_start   DATE NOT NULL,
  reserved_end     DATE NOT NULL,
  status           VARCHAR2(12) DEFAULT 'Reserved' NOT NULL,
  base_charge      NUMBER(10,2) DEFAULT 0 NOT NULL,
  discount_amount  NUMBER(10,2) DEFAULT 0 NOT NULL,
  late_fee         NUMBER(10,2) DEFAULT 0 NOT NULL,
  damage_fee       NUMBER(10,2) DEFAULT 0 NOT NULL,
  cancellation_fee NUMBER(10,2) DEFAULT 0 NOT NULL,
  total_amount     NUMBER(10,2) GENERATED ALWAYS AS (base_charge - discount_amount + late_fee
                                                     + damage_fee + cancellation_fee) VIRTUAL,
  created_at       DATE DEFAULT SYSDATE NOT NULL,
  CONSTRAINT fk_rr_customer FOREIGN KEY (customer_id) REFERENCES Customers(customer_id),
  CONSTRAINT fk_rr_table    FOREIGN KEY (table_id)    REFERENCES Cafe_Tables(table_id),
  CONSTRAINT chk_rr_type    CHECK (booking_type IN ('Dine_In', 'Take_Home')),
  CONSTRAINT chk_rr_status  CHECK (status IN ('Reserved', 'Checked_In', 'Overdue', 'Completed',
                                              'Cancelled', 'No_Show')),
  CONSTRAINT chk_rr_window  CHECK (reserved_end > reserved_start),
  CONSTRAINT chk_booking_type_shape CHECK (
       (booking_type = 'Dine_In'   AND table_id IS NOT NULL
                                   AND party_size IS NOT NULL AND party_size >= 1)
    OR (booking_type = 'Take_Home' AND table_id IS NULL
                                   AND copy_id IS NOT NULL AND party_size IS NULL))
);
CREATE INDEX idx_rr_table_window ON Rentals_Reservations (table_id, reserved_start, reserved_end);

CREATE TABLE Payments (
  payment_id NUMBER(10) GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  booking_id NUMBER(10) NOT NULL,
  amount     NUMBER(10,2) NOT NULL,
  method     VARCHAR2(5) NOT NULL,
  paid_at    DATE DEFAULT SYSDATE NOT NULL,
  CONSTRAINT fk_pay_booking FOREIGN KEY (booking_id) REFERENCES Rentals_Reservations(booking_id),
  CONSTRAINT chk_pay_amount CHECK (amount > 0),
  CONSTRAINT chk_pay_method CHECK (method IN ('Cash', 'Card', 'UPI'))
);
